class Graph:
 def __init__(self,lanes):self.lanes=lanes;self.nodes={};self.edges=[]
 def n(self,i,l,label,shape='action'):self.nodes[i]=(l,label,shape)
 def e(self,a,b,label='',arrow=False,dashed=False):self.edges.append((a,b,label,arrow,dashed))
 def code(self):
  out='flowchart TB\n'
  for l,label in self.lanes.items():
   out+='subgraph lane'+l+'["'+label+'"]\n'
   for i,(lane,txt,shape) in self.nodes.items():
    if lane!=l:continue
    txt=txt.replace('&','&amp;').replace('"','&quot;') or '#160;';forms={'action':'["'+txt+'"]','receive':'(["'+txt+'"])','decision':'{"'+txt+'"}','start':'((" "))','end':'(((" ")))','bar':'[" "]'};out+=i+forms[shape]+'\n'
   out+='end\n'
  for a,b,label,arrow,dashed in self.edges:
   c='-.->' if dashed and arrow else '-.-' if dashed else '-->' if arrow else '---';out+=a+' '+c+(' |"'+label+'"|' if label else '')+' '+b+'\n'
  for i,(_,_,shape) in self.nodes.items():
   if shape in ['start','bar']:out+='style '+i+' fill:#222,stroke:#222,color:#222\n'
  return out.replace('end(((','finalNode(((').replace(' end\n',' finalNode\n')

