 if n==1:
  nodes={'A':'Fund Management Company, Promoter, Transfer Agent','B':'Institutional Investor, Custodian, Distributor','C':'Fund accountant','D':'Transfer Agent, Fund Administrator','E':'Investment manager','F':'New Plan Manager (Transferee)','G':'Old Plan Manager (Transferor)'}
  edges=[('A','B','Fund Reference Data','-->'),('C','D','Price Report','-->'),('B','D','Fund Reference Data','<-->'),('B','D','Account Management','<-->'),('B','D','Order, Status, Order Confirmation','<-->'),('B','D','Statements','<-->'),('B','D','Asset Transfer, Status, Confirmation','<-->'),('D','E','Fund Cash Forecast','-->'),('F','G','Portfolio Transfer','<-->'),('F','D','Asset Transfer, Status, Confirmation','<-->'),('G','D','Asset Transfer, Status, Confirmation','<-->')]
  code='flowchart TB\n'+''.join(i+'["'+v+'"]\n' for i,v in nodes.items())+''.join(a+' '+c+'|"'+l+'"| '+b+'\n' for a,b,l,c in edges)
  notes=['Grouped source labels remain grouped; their coexistence does not equate these institutions or functional roles. Source bank icons are presentation glyphs. Two dashed grouping rectangles surround B and D; they are not labelled systems, so no business system meaning is inferred. The textual edge list preserves the complete communication labels including repeated Status. This is a communication overview, not a timed sequence.']
  for i in ['B','D']:
   code=code.replace(i+'["'+nodes[i]+'"]\n','subgraph group'+i+'[" "]\n'+i+'["'+nodes[i]+'"]\nend\n')
   code+='style group'+i+' fill:#fff,stroke-dasharray:4 4\n'
  return code,nodes,edges,notes
 if n==2:
  left=['Custodian','Institutional Investor','Concentrator','ICSD','CSD','Distributor','Beneficial Owner','Fund Manager'];right=['Market Data Provider','Paying Agent','Custodian','ICSD','Concentrator','CSD','Transfer Agent','Fund Accountant','Distributor'];nodes={'I':'Instructing Party','E':'Executing Party'};edges=[]
  for pref,arr,dest in [('L',left,'I'),('R',right,'E')]:
   for i,l in enumerate(arr):nodes[pref+str(i)]=l;edges.append((pref+str(i),dest,'','-->'))
